<script lang="ts">
 import { onMount } from 'svelte';
 import { defaultAircraft, presets, clone, planform, validateAircraft, type AircraftDefinition, type Controls, type FlightMode, type Wing } from './model';
 import { FlightSimulation, derive, LAUNCH } from './physics';
 import { SceneView } from './scene';
 import { listAircraft, saveAircraft, deleteAircraft, renameAircraft, duplicateAircraft, exportAircraft, importAircraft, readBest, writeBest, History, type SavedAircraft } from './storage';
 import WingEditor from './WingEditor.svelte'; import Parameter from './Parameter.svelte';
 type Tab='机身'|'主翼'|'水平尾翼'|'垂直尾翼'|'组装';
 let host:HTMLDivElement;let scene:SceneView;let sceneReady=$state(false);let simulation:FlightSimulation|null=null;let history=new History(clone(defaultAircraft));let historyVersion=$state(0);
 let aircraft=$state.raw<AircraftDefinition>(clone(defaultAircraft));let tab=$state<Tab>('主翼');let screen=$state<'menu'|'design'|'flight'|'result'>('menu');let mode=$state<FlightMode>('standard');let quality=$state<'Auto'|'High'|'Medium'|'Low'>('Auto');
 let saved=$state.raw<SavedAircraft[]>([]),selectedId=$state(''),message=$state(''),showLibrary=$state(false),debug=$state(false),paused=$state(false),flightReady=$state(false);let best=$state(0);let result=$state<any>(null),hud=$state<any>({speed:0,altitude:LAUNCH.height,distance:0,alpha:0,pitch:0,roll:0,sink:0,glide:0,time:0,liftDragRatio:0,potentialEnergy:0,kineticEnergy:0,dissipatedEnergy:0,initialEnergy:0,launching:true});let perf=$state<any>({});
 let stats=$derived(derive(aircraft));let main=$derived(planform(aircraft.mainWing));let wingKey=$derived<'mainWing'|'horizontalTail'|'verticalTail'>(tab==='水平尾翼'?'horizontalTail':tab==='垂直尾翼'?'verticalTail':'mainWing');
 let recording:ReturnType<FlightSimulation['getRecording']>|null=null;let recordedLength=$state(0);let isReplay=$state(false);let lastDefinition=clone(defaultAircraft),lastMode:FlightMode='standard';
 let weight=$state(0),rudder=$state(0),elevator=$state(0),aileron=$state(0);const keys=new Set<string>();const controls:Controls={weight:0,rudder:0,elevator:0,aileron:0};
 type FlightSample={distance:number;height:number};
 let samples:FlightSample[]=[],lastSampleTime=-Infinity;
 let trajectory=$state.raw<FlightSample[]>([]);
 let chartMaxDistance=$derived(trajectory.reduce<number>((max,p)=>Math.max(max,p.distance),1));
 let chartMaxHeight=$derived(trajectory.reduce<number>((max,p)=>Math.max(max,p.height),LAUNCH.height));
 let chartPoints=$derived(trajectory.map(p=>`${(38+p.distance/chartMaxDistance*290).toFixed(2)},${(98-p.height/chartMaxHeight*76).toFixed(2)}`).join(' '));
 let energyParts=$derived([{key:'potential',name:'势能',value:hud.potentialEnergy},{key:'kinetic',name:'动能',value:hud.kineticEnergy},{key:'dissipated',name:'已耗散',value:hud.dissipatedEnergy}]);
 let energyTotal=$derived(hud.potentialEnergy+hud.kineticEnergy+hud.dissipatedEnergy);
 let assemblyPositions=$derived([{key:'mainWing',label:'主翼纵向位置',value:aircraft.assembly.mainWing,min:-6,max:5},{key:'mainWingHeight',label:'主翼安装高度',value:aircraft.assembly.mainWingHeight,min:0,max:2},{key:'horizontalTail',label:'水平尾翼位置',value:aircraft.assembly.horizontalTail,min:-6,max:5},{key:'verticalTail',label:'垂直尾翼位置',value:aircraft.assembly.verticalTail,min:-6,max:5},{key:'cockpit',label:'驾驶舱位置',value:aircraft.cockpit.position,min:-3,max:4}] as const);
 function setPosition(key:typeof assemblyPositions[number]['key'],input:HTMLInputElement){const n=input.valueAsNumber;if(Number.isFinite(n)){change(d=>{if(key==='cockpit')d.cockpit.position=n;else d.assembly[key]=n;});commit();}else notify('位置必须是有限数值');input.value=String(key==='cockpit'?aircraft.cockpit.position:aircraft.assembly[key]);}
 $effect(()=>{const target=screen==='design'?(tab==='组装'?'assembly':tab==='机身'?null:wingKey):null;if(sceneReady)scene.setEditor(target,d=>change(out=>Object.assign(out,d)),commit);});
 function sampleFlight(final=false){if(!simulation||simulation.launching)return;if(final||simulation.time-lastSampleTime>=0.1){samples.push({distance:simulation.telemetry.distance,height:simulation.telemetry.altitude});lastSampleTime=simulation.time;}}
 function refreshHud(){if(!simulation)return;const t=simulation.telemetry;hud={...t,alpha:t.alpha*180/Math.PI,pitch:t.pitch*180/Math.PI,roll:t.roll*180/Math.PI,time:simulation.time,launching:simulation.launching};}
 function refreshTrajectory(){if(trajectory.length!==samples.length)trajectory=samples.slice();}
 const hints:Record<Tab,string>={'机身':'驾驶舱的位置改变重心。过度靠后可能让飞机俯仰失稳。','主翼':'拖动四个顶点或 1–4 根弦、2–3 梢弦线段。沿屏幕垂直方向轻吸附，按住 Ctrl 取消。增加面积降低翼载荷，但增加重量与阻力。','水平尾翼':'拖动顶点或 1–4 根弦、2–3 梢弦线段。沿屏幕垂直方向轻吸附，按住 Ctrl 取消。增大尾翼或后移安装位置，通常提高俯仰稳定性。','垂直尾翼':'侧视拖动顶点或 1–4 根弦、2–3 梢弦线段。沿屏幕垂直方向轻吸附，按住 Ctrl 取消。垂直尾翼提供偏航恢复力矩，太小容易偏离航向。','组装':'侧视直接拖动主翼、尾翼或驾驶舱。主翼可上下移动；沿屏幕垂直方向轻吸附，按住 Ctrl 取消。正 X 朝机头，安装角改变有效攻角。'};
 function notify(s:string){message=s;}
 function commit(){try{validateAircraft(aircraft);history.push(clone(aircraft));historyVersion++;}catch(e){notify((e as Error).message);}}
 function change(mutator:(d:AircraftDefinition)=>void){const d=clone(aircraft);mutator(d);try{validateAircraft(d);aircraft=d;scene?.updateAircraft(d);}catch(e){notify((e as Error).message);}}
 function replace(d:AircraftDefinition){aircraft=clone(d);scene?.updateAircraft(aircraft);commit();}
 function undo(){const d=history.undo();if(d){aircraft=clone(d);selectedId='';scene?.updateAircraft(aircraft);historyVersion++;}}
 function redo(){const d=history.redo();if(d){aircraft=clone(d);selectedId='';scene?.updateAircraft(aircraft);historyVersion++;}}
 function library(){try{saved=listAircraft();showLibrary=!showLibrary;}catch(e){notify((e as Error).message);}}
 function save(){try{const item=saveAircraft(aircraft,selectedId||undefined);selectedId=item.id;saved=listAircraft();notify('飞机已保存在此浏览器');}catch(e){notify((e as Error).message);}}
 function load(id:string){const item=saved.find(s=>s.id===id);if(item){replace(item.definition);selectedId=id;notify('已加载 '+item.name);}}
 function renameSaved(id:string,name:string){try{const item=renameAircraft(id,name);saved=listAircraft();if(selectedId===id){change(d=>d.name=item.name);commit();}}catch(e){notify((e as Error).message);}}
 function fileExport(){const url=URL.createObjectURL(new Blob([exportAircraft(aircraft)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=aircraft.name+'.json';a.click();URL.revokeObjectURL(url);}
 async function fileImport(e:Event){const input=e.target as HTMLInputElement;try{const f=input.files?.[0];if(f){if(f.size>100000)throw Error('文件超过 100 KB');replace(importAircraft(await f.text()));selectedId='';notify('导入成功');}}catch(e){notify('导入失败：'+(e as Error).message);}input.value='';}
 function clearControls(){keys.clear();weight=rudder=elevator=aileron=0;controls.weight=controls.rudder=controls.elevator=controls.aileron=0;}
 function start(replay=false){try{lastDefinition=replay?lastDefinition:clone(aircraft);lastMode=replay?lastMode:mode;simulation=new FlightSimulation(lastDefinition,lastMode);if(replay&&recording)simulation.loadReplay(recording);samples=[];trajectory=[];lastSampleTime=-Infinity;refreshHud();isReplay=replay;screen='flight';result=null;paused=false;flightReady=false;clearControls();scene.setEditor(null,d=>change(out=>Object.assign(out,d)),commit);scene.setFlight(simulation);scene.setDebug(debug||lastMode==='experimental');scene.cameraView('追尾');}catch(e){notify((e as Error).message);}}
 function beginFlight(){if(screen!=='flight'||!simulation||flightReady)return;clearControls();paused=false;flightReady=true;}
 function togglePause(){if(screen==='flight'&&flightReady)paused=!paused;}
 function finish(){if(!simulation)return;sampleFlight(true);refreshHud();refreshTrajectory();result=simulation.result;recordedLength=simulation.recordingLength;screen='result';if(!isReplay){recording=simulation.getRecording();try{best=writeBest(mode,result.distance);}catch(e){notify((e as Error).message);}}}
 function design(){screen='design';simulation=null;flightReady=false;scene?.setFlight(null);scene?.updateAircraft(aircraft);scene?.cameraView('轨道');clearControls();}
 function keyboard(e:KeyboardEvent,down:boolean){if((e.target as HTMLElement).matches('input,select,textarea'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(down&&screen==='flight'&&flightReady)keys.add(e.key.toLowerCase());else keys.delete(e.key.toLowerCase());if(down&&!e.repeat&&e.key===' ')togglePause();if(down&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}}
 onMount(()=>{scene=new SceneView(host);scene.updateAircraft(aircraft);sceneReady=true;let previous=performance.now(),accumulator=0,lastInstruments=0;let request=0;
 const tick=(now:number)=>{let elapsed=Math.min((now-previous)/1000,0.1);previous=now;if(!document.hidden){if(screen==='flight'&&simulation&&flightReady&&!paused){accumulator+=elapsed;let steps=0;while(accumulator>=1/60&&steps<5){controls.weight=Math.max(-1,Math.min(1,weight+(keys.has('arrowup')||keys.has('w')?1:0)-(keys.has('arrowdown')||keys.has('s')?1:0)));controls.rudder=Math.max(-1,Math.min(1,rudder+(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0)));controls.elevator=elevator;controls.aileron=aileron;simulation.step(controls,1/60);sampleFlight();accumulator-=1/60;steps++;if(simulation.ended){finish();accumulator=0;break;}}if(steps===5)accumulator=0;}else accumulator=0;scene.render(elapsed);if(screen==='flight')refreshHud();if(now-lastInstruments>150){refreshTrajectory();perf={...scene.metrics,physicsMs:simulation?.telemetry.physicsMs??0};lastInstruments=now;}}request=requestAnimationFrame(tick);};request=requestAnimationFrame(tick);
 const down=(e:KeyboardEvent)=>keyboard(e,true),up=(e:KeyboardEvent)=>keyboard(e,false),blur=clearControls;window.addEventListener('keydown',down);window.addEventListener('keyup',up);window.addEventListener('blur',blur);document.addEventListener('visibilitychange',blur);
 try{saved=listAircraft();best=readBest(mode);}catch(e){notify((e as Error).message);}
 // Read-only diagnostics for automated measurement; interaction tests still use visible controls.
 Object.assign(window,{glider:{get aircraft(){return clone(aircraft)},get state(){return screen},get flightReady(){return flightReady},get time(){return simulation?.time??0},get recordingLength(){return simulation?.recordingLength??0},get scene(){return scene.getDiagnostics()},get trajectory(){return samples.map(p=>({...p}))},get metrics(){return {...scene.metrics,physicsMs:simulation?.telemetry.physicsMs??0}},get telemetry(){return simulation?.telemetry},get result(){return result}}});
 return()=>{cancelAnimationFrame(request);scene.dispose();window.removeEventListener('keydown',down);window.removeEventListener('keyup',up);window.removeEventListener('blur',blur);document.removeEventListener('visibilitychange',blur);};});
 function touch(e:PointerEvent,key:'weight'|'rudder',value:number){if(!flightReady)return;e.currentTarget instanceof HTMLElement&&e.currentTarget.setPointerCapture(e.pointerId);if(key==='weight')weight=value;else rudder=value;}
</script>
<svelte:head><title>无动力滑翔 · 设计与飞行</title></svelte:head>
{#snippet energyPanel()}
 <section class="energy-panel" aria-label="离台能量守恒">
 <div class="instrument-heading"><h2>能量分配</h2><span>{!flightReady?'待开始':hud.launching?'助跑供能中':'离台后总量恒定'}</span></div>
 {#if hud.launching}
 <p class="launch-note">{!flightReady?'点击开始后助跑':'平台助跑中'}，加速至 {LAUNCH.speed.toFixed(1)} m/s。离台时建立能量基准，助跑外力供能不计入耗散。</p>
 {:else}
 <div class="energy-track" aria-hidden="true">{#each energyParts as part}<span class={part.key} style:width={`${hud.initialEnergy>0?part.value/hud.initialEnergy*100:0}%`}></span>{/each}</div>
 <dl class="energy-values">{#each energyParts as part}<div class={part.key}><dt>{part.name}</dt><dd>{part.value.toFixed(0)} J <small>{(hud.initialEnergy>0?part.value/hud.initialEnergy*100:0).toFixed(1)}%</small></dd></div>{/each}</dl>
 <p class="energy-total">合计 {energyTotal.toFixed(0)} J <span>基准 {hud.initialEnergy.toFixed(0)} J · 100%</span></p>
 <p class="energy-caption">动能含平动与转动；耗散含空气阻力与阻尼损失。</p>
 {/if}
 </section>
{/snippet}
{#snippet altitudeCurve()}
 <section class="trajectory-panel" aria-label="距离高度曲线">
 <div class="instrument-heading"><h2>距离—高度</h2><span>{trajectory.length?`真实采样 ${trajectory.length} 点`:'离台后开始采样'}</span></div>
 <svg viewBox="0 0 348 124" role="img" aria-label={`飞行轨迹，水平距离0至${chartMaxDistance.toFixed(1)}米，高度0至${chartMaxHeight.toFixed(1)}米`}>
 <line class="chart-grid" x1="38" y1="22" x2="328" y2="22"/><line class="chart-grid" x1="38" y1="60" x2="328" y2="60"/><path class="chart-axis" d="M38 16V98H330"/>
 <text x="2" y="25">{chartMaxHeight.toFixed(1)}</text><text x="23" y="101">0</text><text x="38" y="116">0</text><text x="328" y="116" text-anchor="end">{chartMaxDistance.toFixed(1)} m</text><text x="3" y="12">高度 m</text>
 {#if trajectory.length}{@const last=trajectory[trajectory.length-1]}<polyline class="chart-line" points={chartPoints}/><circle class="chart-current" cx={38+last.distance/chartMaxDistance*290} cy={98-last.height/chartMaxHeight*76} r="3"/>{/if}
 </svg>
 <p class="chart-caption">离台后每 0.1 s 采样，末点保留实际终止高度。</p>
 </section>
{/snippet}
<div class="app" class:flying={screen==='flight'} class:designing={screen==='design'}>
 <div class="scene" bind:this={host} aria-label="三维滑空机与湖面场景"></div>
 <header class="topbar"><button class="brand" onclick={()=>screen==='flight'?togglePause():screen='menu'} aria-label="返回主菜单"><svg viewBox="0 0 36 28" width="34" height="28" fill="none" aria-hidden="true"><path d="M2 10 33 3 23 13 19 25 14 14 2 10Z" stroke="currentColor" stroke-width="1.7"/><path d="m14 14 19-11" stroke="currentColor"/></svg><span>无动力滑翔<small>UNPOWERED GLIDING</small></span></button><nav aria-label="游戏流程"><button class:active={screen==='design'} onclick={design}>设计</button><button class:active={screen==='flight'||screen==='result'} onclick={()=>start()}>试飞</button></nav><div class="top-actions"><label class="quality-label">画质 <select aria-label="画质" bind:value={quality} onchange={()=>scene?.setQuality(quality)}><option>Auto</option><option>High</option><option>Medium</option><option>Low</option></select></label><button class="text-button" onclick={()=>{debug=!debug;scene?.setDebug(debug);}} aria-pressed={debug}>性能</button></div></header>
 {#if screen==='menu'}
 <main class="welcome"><h1>让设计，<br/>乘风而起。</h1><p>一架轻盈的飞机，一片开阔的湖。<br/>从机翼的每一条线开始，寻找更远的可能。</p><button class="primary large" onclick={design}>开始设计 <span>↗</span></button><button class="secondary" onclick={()=>start()}>先试飞默认飞机</button><div class="welcome-note">{LAUNCH.height} m 平台 · 助跑后无动力滑翔 · 本地保存</div></main>
 <aside class="menu-caption"><span>湖风 01 / 均衡型</span><p>14.0 m 翼展 <b>·</b> 参数化轻型滑空机</p></aside>
 {:else if screen==='design'}
 <aside class="editor"><div class="editor-heading"><div><h1>飞机工坊</h1><p>每一次调整，都是下一次远航。</p></div><button class="text-button" onclick={library}>机库</button></div><div class="name-row"><input aria-label="飞机名称" value={aircraft.name} maxlength="60" onchange={e=>{change(d=>d.name=e.currentTarget.value);commit();}}/><button onclick={save}>保存</button></div><div class="history"><button disabled={!historyVersion||!history.canUndo} onclick={undo}>撤销</button><button disabled={!historyVersion||!history.canRedo} onclick={redo}>重做</button><button onclick={()=>{replace(defaultAircraft);selectedId='';}}>重置设计</button></div>
 <div class="tabs" role="tablist" aria-label="部件编辑">{#each ['机身','主翼','水平尾翼','垂直尾翼','组装'] as t}<button role="tab" aria-selected={tab===t} class:active={tab===t} onclick={()=>tab=t as Tab}>{t}</button>{/each}</div>
 <div class="editor-content"><h2>{tab==='组装'?'位置与配平':tab+'设计'}</h2><p class="help">{hints[tab]}</p>
 {#if tab==='机身'}
 <Parameter label="机身长度" value={aircraft.fuselage.length} min={3} max={12} unit="m" onchange={n=>change(d=>d.fuselage.length=n)} oncommit={commit} hint="长度增加结构重量。尾翼位置可在组装中独立调整。"/>
 <Parameter label="驾驶舱位置" value={aircraft.cockpit.position} min={-3} max={4} unit="m" onchange={n=>change(d=>d.cockpit.position=n)} oncommit={commit} hint="正值向机头移动。驾驶员是整机主要质量来源。"/>
 <Parameter label="驾驶员质量" value={aircraft.pilot.mass} min={40} max={100} step={1} unit="kg" onchange={n=>change(d=>d.pilot.mass=n)} oncommit={commit}/>
 <Parameter label="重心操纵行程" value={aircraft.controls.travel} min={0.1} max={0.8} step={0.05} unit="m" onchange={n=>change(d=>d.controls.travel=n)} oncommit={commit}/>
 {:else if tab==='组装'}
 <div class="assembly-positions" aria-label="组装位置精确值">
 {#each assemblyPositions as position}<label><span>{position.label}</span><input aria-label={position.label+'精确值'} type="number" min={position.min} max={position.max} step="0.1" value={position.value} onchange={e=>setPosition(position.key,e.currentTarget)}/><small>m</small></label>{/each}
 </div>
 <Parameter label="主翼安装角" value={aircraft.assembly.mainIncidence} min={-10} max={18} unit="°" onchange={n=>change(d=>d.assembly.mainIncidence=n)} oncommit={commit} hint="提高安装角会增加有效攻角；过大可能失速。"/>
 <Parameter label="水平尾翼安装角" value={aircraft.assembly.tailIncidence} min={-12} max={12} unit="°" onchange={n=>change(d=>d.assembly.tailIncidence=n)} oncommit={commit} hint="调节尾翼安装角以配平，观察离台后攻角与俯仰变化。"/>
 <div class="stability" aria-label="重心与升力中心配平参考"><b>重心 CG · X {stats.cg.x.toFixed(2)} m</b><span>全机升力参考中心 · X {stats.aerodynamics.liftCenter?stats.aerodynamics.liftCenter.x.toFixed(2)+' m':'无合力'}</span><span>全机阻力参考中心 · X {stats.aerodynamics.dragCenter?stats.aerodynamics.dragCenter.x.toFixed(2)+' m':'无合力'}</span><span>全机中性点估算 · X {stats.neutralPoint.toFixed(2)} m</span><span>重心位置 {((stats.mainQuarterChord.x+main.chord*0.25-stats.cg.x)/main.chord*100).toFixed(1)}% MAC（主翼前缘起）</span><strong>静稳定裕度 {(stats.staticMargin*100).toFixed(1)}% MAC</strong><p>升力与阻力标记来自三翼合力，位置为等效参考中心，不表示力矩为零。主翼 MAC 长 {main.chord.toFixed(2)} m，1/4 弦几何参考 X {stats.mainQuarterChord.x.toFixed(2)} m。</p><p>中性点含水平尾翼效率估算。建议先试 5–20% 正稳定裕度，再用安装角配平。</p><p>{stats.staticMargin<0?'重心偏后：可能俯仰失稳。前移驾驶舱或后移尾翼。':stats.staticMargin>0.35?'重心偏前：可能难以抬头。后移驾驶舱并留意失速。':'具备正稳定裕度，不代表已配平；试飞观察攻角，避免大攻角失速。'}</p></div>
 {:else}
 {#key wingKey}<WingEditor value={aircraft[wingKey]} vertical={tab==='垂直尾翼'} onchange={(w:Wing)=>change(d=>d[wingKey]=w)} oncommit={commit}/>{/key}
 {#if tab==='主翼'}<Parameter label="主翼上反角" value={aircraft.mainWing.dihedral} min={0} max={25} unit="°" onchange={n=>change(d=>d.mainWing.dihedral=n)} oncommit={commit} hint="增加侧滑时的滚转恢复效应，不会强制飞机自动水平。"/>{/if}
 {/if}
 <section class="aero-preview" aria-label="三翼气动力预览"><h3>三翼气动力预览</h3><p>同一物理模型 · 空速 {stats.aerodynamics.speed.toFixed(0)} m/s · 攻角 {(stats.aerodynamics.alpha*180/Math.PI).toFixed(0)}° · 侧滑 {(stats.aerodynamics.beta*180/Math.PI).toFixed(0)}° · 无操纵</p>{#each stats.aerodynamics.wings as wing}<div class="aero-wing" aria-label={wing.name+'气动作用'}><b>{wing.name}</b><span>{wing.kind==='vertical'?'侧向力':'升力'} {(wing.kind==='vertical'?wing.lift.z:wing.lift.y).toFixed(1)} N · 阻力 {wing.drag.length().toFixed(1)} N</span><span>有效攻角 {(wing.alpha*180/Math.PI).toFixed(1)}° · {wing.area.toFixed(2)} m² · {wing.kind==='vertical'?'偏航力矩':'俯仰力矩'} {(wing.kind==='vertical'?wing.torque.y:wing.torque.z).toFixed(1)} N·m</span></div>{/each}</section>
 <div class="preset"><label for="preset">试试不同设计</label><select id="preset" aria-label="预设飞机" onchange={e=>{const n=+e.currentTarget.value;if(n>=0){replace(presets[n]);selectedId='';}}}><option value="-1">选择预设飞机</option>{#each presets as p,i}<option value={i}>{p.name}</option>{/each}</select></div>
 </div><div class="editor-footer"><label>飞行模式<select aria-label="飞行模式" bind:value={mode} onchange={()=>{try{best=readBest(mode);}catch{best=0;}}}><option value="standard">标准 · 公平竞赛</option><option value="assisted">辅助 · 额外阻尼</option><option value="experimental">实验 · 完整操纵</option></select></label><button class="primary" onclick={()=>start()}>前往平台试飞 <span>↗</span></button></div></aside>
 <div class="viewport-tools" aria-label="设计相机">{#each ['轨道','俯视','侧视','正视','后视'] as c}<button disabled={tab!=='机身'&&c!==(tab==='垂直尾翼'||tab==='组装'?'侧视':'俯视')} onclick={()=>scene.cameraView(c)}>{c}</button>{/each}</div><div class="scene-hint"><span>{tab==='机身'?'拖动旋转 · 双指缩放 · 右键平移':tab==='组装'?'侧视锁定 · 拖动实体部件 · Ctrl 取消轻吸附':'拖动顶点或根弦/梢弦 · Ctrl 取消垂直轻吸附'}</span><span><i class="cg"></i> 重心 CG <i class="lift"></i> 升力 <i class="drag"></i> 阻力</span></div>
 <section class="design-metrics" aria-label="飞机性能估算"><div><small>机翼面积</small><strong>{main.area.toFixed(2)} <em>m²</em></strong></div><div><small>翼展 / 展弦比</small><strong>{main.span.toFixed(1)} <em>m / {main.aspect.toFixed(1)}</em></strong></div><div><small>全备质量</small><strong>{stats.mass.toFixed(1)} <em>kg</em></strong></div><div><small>翼载荷</small><strong>{stats.wingLoading.toFixed(2)} <em>kg/m²</em></strong></div><div><small>估算最佳滑翔比</small><strong>{stats.glideRatio.toFixed(1)} <em>: 1</em></strong></div></section>
 {:else if screen==='flight'}
 <section class="flight-hud" aria-label="飞行数据"><div><small>滑翔距离</small><strong>{hud.distance.toFixed(1)}<em>m</em></strong></div><div><small>空速</small><strong>{hud.speed.toFixed(1)}<em>m/s</em></strong></div><div><small>高度</small><strong>{hud.altitude.toFixed(1)}<em>m</em></strong></div><div><small>总计时</small><strong>{hud.time.toFixed(1)}<em>s</em></strong></div><div><small>实时攻角</small><strong>{hud.alpha.toFixed(1)}<em>°</em></strong></div><div><small>实时升阻比</small><strong>{Number.isFinite(hud.liftDragRatio)?hud.liftDragRatio.toFixed(1):'—'}<em>:1</em></strong></div></section>
 <div class="flight-status"><span>{!flightReady?'平台待开始 · 点击开始后助跑':hud.launching?'平台助跑 · 外力加速，离台后开始计分':'无动力滑翔 · 距离与能量以离台为基准'}</span><span>{isReplay?'输入重放':mode==='assisted'?'辅助模式 · 独立成绩':mode==='experimental'?'实验模式':'标准模式 · 无风'} · 总计时含助跑</span>{#if hud.stall}<b>攻角过大 · 失速</b>{/if}</div>
 <div class="flight-instruments">{@render energyPanel()}{@render altitudeCurve()}</div>
 <div class="flight-tools">{#if !flightReady}<button class="primary" aria-label="开始试飞" onclick={beginFlight}>开始</button>{/if}<button disabled={!flightReady} onclick={togglePause}>{paused?'继续飞行':'暂停'}</button><select aria-label="飞行相机" onchange={e=>scene.cameraView(e.currentTarget.value)}>{#each ['追尾','侧面','驾驶员','自由'] as c}<option>{c}</option>{/each}</select><button onclick={design}>返回设计</button></div>
 {#if paused}<div class="pause-banner">飞行已暂停 <button onclick={()=>paused=false}>继续</button></div>{/if}
 <div class="flight-controls"><div><span>重心前后 · W / S</span><button disabled={!flightReady} aria-label="重心前移" onpointerdown={e=>touch(e,'weight',1)} onpointerup={()=>weight=0} onpointercancel={()=>weight=0}>前移</button><button disabled={!flightReady} aria-label="重心后移" onpointerdown={e=>touch(e,'weight',-1)} onpointerup={()=>weight=0} onpointercancel={()=>weight=0}>后移</button><progress max="2" value={weight+1} aria-label="重心操纵输入"></progress></div><div><span>方向舵 · A / D</span><button disabled={!flightReady} aria-label="向左转向" onpointerdown={e=>touch(e,'rudder',-1)} onpointerup={()=>rudder=0} onpointercancel={()=>rudder=0}>左转</button><button disabled={!flightReady} aria-label="向右转向" onpointerdown={e=>touch(e,'rudder',1)} onpointerup={()=>rudder=0} onpointercancel={()=>rudder=0}>右转</button><progress max="2" value={rudder+1} aria-label="方向操纵输入"></progress></div></div>
 <details class="advanced-hud"><summary>姿态与操纵</summary><p>俯仰 {hud.pitch.toFixed(1)}° · 滚转 {hud.roll.toFixed(1)}°</p><p>下沉率 {hud.sink.toFixed(2)} m/s · 航迹滑翔比 {Number.isFinite(hud.glide)?hud.glide.toFixed(1):'—'}</p>{#if mode==='experimental'}<label>升降舵<input disabled={!flightReady} aria-label="升降舵" type="range" min="-1" max="1" step="0.05" bind:value={elevator}/></label><label>副翼<input disabled={!flightReady} aria-label="副翼" type="range" min="-1" max="1" step="0.05" bind:value={aileron}/></label>{/if}</details>
 {:else if screen==='result'&&result}
 <section class="results"><div class="result-heading"><h1>每一米，都来自你的设计。</h1><span>{isReplay?'飞行重放':mode==='assisted'?'辅助组成绩':mode==='experimental'?'实验组成绩':'标准组成绩'}</span></div><div class="score">{result.distance.toFixed(2)}<small>m</small></div><p class="best">个人最佳 {best.toFixed(2)} m · {result.landing==='water'?'接触湖面':result.landing==='platform'?'撞击平台':result.landing==='terrain'?'撞击地形':'达到飞行边界'}</p><dl class="result-statistics"><div><dt>总计时（含助跑）</dt><dd>{result.time.toFixed(2)} s</dd></div><div><dt>平均速度</dt><dd>{result.averageSpeed.toFixed(2)} m/s</dd></div><div><dt>最高速度</dt><dd>{result.maxSpeed.toFixed(2)} m/s</dd></div><div><dt>最低速度</dt><dd>{result.minSpeed.toFixed(2)} m/s</dd></div><div><dt>最大高度</dt><dd>{result.maxHeight.toFixed(2)} m</dd></div><div><dt>输入记录</dt><dd>{recordedLength} 步 · 60 Hz</dd></div></dl><div class="result-instruments">{@render altitudeCurve()}</div><div class="result-actions"><button class="primary" onclick={design}>返回设计改进</button><button onclick={()=>start()}>再试一次</button><button onclick={()=>start(true)}>重放飞行</button></div></section>
 {/if}
 {#if showLibrary&&screen==='design'}<section class="library" aria-label="本地机库"><div class="library-title"><h2>本地机库</h2><button onclick={()=>showLibrary=false}>关闭</button></div><p>飞机保存在当前浏览器。导出 JSON 可备份或分享。</p><div class="library-actions"><button onclick={save}>保存当前飞机</button><button onclick={fileExport}>导出 JSON</button><label class="button">导入 JSON<input aria-label="导入飞机文件" type="file" accept=".json,application/json" onchange={fileImport}/></label></div>{#if !saved.length}<p class="empty">机库还没有飞机。先保存你的第一个设计。</p>{/if}{#each saved as s}<article class="saved-plane"><input aria-label={'重命名'+s.name} value={s.name} maxlength="60" onchange={e=>renameSaved(s.id,e.currentTarget.value)}/><small>{new Date(s.updatedAt).toLocaleString()}</small><div><button onclick={()=>load(s.id)}>加载</button><button onclick={()=>{try{duplicateAircraft(s.id);saved=listAircraft();}catch(e){notify((e as Error).message);}}}>复制</button><button onclick={()=>{if(confirm('删除“'+s.name+'”？此操作不可撤销。')){try{deleteAircraft(s.id);saved=listAircraft();if(selectedId===s.id)selectedId='';}catch(e){notify((e as Error).message);}}}}>删除</button></div></article>{/each}</section>{/if}
 {#if debug}<aside class="performance" aria-label="开发性能面板"><h2>性能实测 <button onclick={()=>debug=false}>关闭</button></h2><p>{perf.quality} · {Number(perf.fps||0).toFixed(1)} FPS</p><p>平均 {Number(perf.mean||0).toFixed(2)} ms · P95 {Number(perf.p95||0).toFixed(2)} ms · P99 {Number(perf.p99||0).toFixed(2)} ms</p><p>物理 {Number(perf.physicsMs||0).toFixed(3)} ms · 渲染提交 {Number(perf.renderMs||0).toFixed(2)} ms</p><p>几何 {Number(perf.geometryMs||0).toFixed(2)} ms · {perf.drawCalls||0} draw calls · {perf.triangles||0} triangles</p><p>几何与纹理估算 {typeof perf.memory==='number'?perf.memory.toFixed(2)+' MiB':'不可用'}</p><small>帧率来自当前环境，不代表真实手机性能。</small></aside>{/if}
 {#if message}<div class="toast" role="status">{message}<button aria-label="关闭提示" onclick={()=>message=''}>关闭</button></div>{/if}
</div>
